1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
6	<title>Receipt</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500&display=swap" rel="stylesheet">
10	<style>
11	  /* Tokens: the variables defined in bench.pen */
12	  :root {
13	    --bg: #F5F3EE;
14	    --surface: #FFFFFF;
15	    --text-primary: #14161A;
16	    --text-secondary: #5F6672;
17	    --divider: #E6E3DC;
18	    --success: #0B7A4B;
19	    --success-bg: #DDF0E5;
20	    --success-text: #075C38;
21	    --pending: #8A5300;
22	    --pending-bg: #FBEFD5;
23	    --danger: #B42318;
24	    --danger-bg: #FBE4E1;
25	    --font-body: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
26	    --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
27	    --radius-card: 16px;
28	    --radius-button: 14px;
29	    --gutter: 20px;
30	  }
31	
32	  *, *::before, *::after { box-sizing: border-box; }
33	  html { -webkit-text-size-adjust: 100%; }
34	  body {
35	    margin: 0;
36	    background: var(--bg);
37	    color: var(--text-primary);
38	    font-family: var(--font-body);
39	    font-size: 15px;
40	    line-height: 1.35;
41	  }
42	  button { font: inherit; color: inherit; }
43	  svg { flex: none; }
44	  .visually-hidden {
45	    position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
46	    overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
47	  }
48	  :focus-visible { outline: 2px solid var(--text-primary); outline-offset: 2px; }
49	
50	  /* App column: full screen on phones, a centred phone-width column on larger screens */
51	  .app {
52	    display: flex;
53	    flex-direction: column;
54	    min-height: 100vh;
55	    min-height: 100dvh;
56	    max-width: 430px;
57	    margin: 0 auto;
58	    background: var(--bg);
59	  }
60	
61	  .header {
62	    display: grid;
63	    place-items: center;
64	    min-height: 52px;
65	    padding-top: env(safe-area-inset-top);
66	  }
67	  .header h1 { margin: 0; font-size: 17px; font-weight: 600; }
68	
69	  .body {
70	    flex: 1;
71	    display: flex;
72	    flex-direction: column;
73	    gap: 24px;
74	    padding: 8px var(--gutter) 20px;
75	  }
76	
77	  /* Hero */
78	  .hero {
79	    display: flex;
80	    flex-direction: column;
81	    align-items: center;
82	    gap: 10px;
83	    padding-top: 4px;
84	    text-align: center;
85	  }
86	  .pill {
87	    display: inline-flex;
88	    align-items: center;
89	    gap: 8px;
90	    padding: 6px 14px 6px 8px;
91	    border-radius: 999px;
92	    font-weight: 600;
93	  }
94	  .pill__icon {
95	    display: grid;
96	    place-items: center;
97	    width: 22px; height: 22px;
98	    border-radius: 50%;
99	    color: #FFFFFF;
100	  }
101	  .pill--success { background: var(--success-bg); color: var(--success-text); }
102	  .pill--success .pill__icon { background: var(--success); }
103	  .pill--pending { background: var(--pending-bg); color: var(--pending); }
104	  .pill--pending .pill__icon { background: var(--pending); }
105	  .pill--failed { background: var(--danger-bg); color: var(--danger); }
106	  .pill--failed .pill__icon { background: var(--danger); }
107	
108	  .amount {
109	    margin: 0;
110	    font-size: clamp(40px, 13vw, 52px);
111	    font-weight: 700;
112	    letter-spacing: -0.03em;
113	    line-height: 1.1;
114	    font-variant-numeric: tabular-nums;
115	    overflow-wrap: anywhere;
116	  }
117	  .merchant { margin: 0; font-size: 16px; color: var(--text-secondary); overflow-wrap: anywhere; }
118	  .state-message { margin: 0; max-width: 300px; font-size: 14px; line-height: 1.4; color: var(--text-secondary); }
119	
120	  /* Details card */
121	  .card {
122	    margin: 0;
123	    padding: 0 16px;
124	    background: var(--surface);
125	    border-radius: var(--radius-card);
126	  }
127	  .row {
128	    display: flex;
129	    justify-content: space-between;
130	    align-items: flex-start;
131	    gap: 16px;
132	    padding: 14px 0;
133	    border-bottom: 1px solid var(--divider);
134	  }
135	  .row:last-child { border-bottom: 0; }
136	  .row dt { color: var(--text-secondary); flex: none; }
137	  .row dd {
138	    margin: 0;
139	    display: flex;
140	    flex-direction: column;
141	    align-items: flex-end;
142	    gap: 3px;
143	    min-width: 0;
144	    text-align: right;
145	  }
146	  .row__value { font-weight: 500; overflow-wrap: anywhere; }
147	  .row__value--strong { font-weight: 700; }
148	  .row__sub { font-size: 13px; color: var(--text-secondary); }
149	
150	  /* The whole Transaction ID row is the copy target (44px+ tall) */
151	  .row--copy { padding: 0; align-items: stretch; }
152	  .row--copy dd { flex: 1; align-items: stretch; }
153	  .copy-button {
154	    display: flex;
155	    justify-content: space-between;
156	    align-items: center;
157	    gap: 16px;
158	    width: 100%;
159	    min-height: 56px;
160	    padding: 6px 0;
161	    border: 0;
162	    background: none;
163	    cursor: pointer;
164	    text-align: left;
165	  }
166	  .copy-button__label { color: var(--text-secondary); }
167	  .copy-button__value {
168	    display: inline-flex;
169	    align-items: center;
170	    gap: 8px;
171	    font-family: var(--font-mono);
172	    font-size: 14px;
173	    font-weight: 500;
174	  }
175	
176	  /* Help row */
177	  .help {
178	    display: flex;
179	    align-items: center;
180	    gap: 12px;
181	    width: 100%;
182	    padding: 16px;
183	    border: 0;
184	    border-radius: var(--radius-card);
185	    background: var(--surface);
186	    cursor: pointer;
187	    text-align: left;
188	  }
189	  .help__text { flex: 1; display: flex; flex-direction: column; gap: 2px; }
190	  .help__title { font-weight: 600; }
191	  .help__sub { font-size: 13px; color: var(--text-secondary); }
192	
193	  /* Footer stays pinned while the body scrolls (critique C-07) */
194	  .footer {
195	    position: sticky;
196	    bottom: 0;
197	    display: flex;
198	    gap: 12px;
199	    padding: 12px var(--gutter) max(20px, env(safe-area-inset-bottom));
200	    background: var(--bg);
201	    border-top: 1px solid var(--divider);
202	  }
203	  .button {
204	    display: inline-flex;
205	    align-items: center;
206	    justify-content: center;
207	    gap: 8px;
208	    min-height: 52px;
209	    padding: 0 18px;
210	    border-radius: var(--radius-button);
211	    font-size: 16px;
212	    font-weight: 600;
213	    cursor: pointer;
214	    white-space: nowrap;
215	  }
216	  .button--primary { flex: 1; border: 0; background: var(--text-primary); color: #FFFFFF; }
217	  .button--secondary { border: 1px solid var(--text-primary); background: transparent; }
218	  .button:active, .help:active, .copy-button:active { opacity: 0.7; }
219	  .button[aria-busy="true"] { cursor: progress; opacity: 0.7; }
220	  .spinner {
221	    width: 18px; height: 18px;
222	    border: 2px solid currentColor;
223	    border-right-color: transparent;
224	    border-radius: 50%;
225	    animation: spin 0.8s linear infinite;
226	  }
227	  @keyframes spin { to { transform: rotate(360deg); } }
228	
229	  /* Loading skeleton */
230	  .bone { display: block; border-radius: 8px; background: var(--divider); }
231	
232	  /* Toast */
233	  .toast {
234	    position: fixed;
235	    left: 50%;
236	    bottom: calc(96px + env(safe-area-inset-bottom));
237	    transform: translate(-50%, 8px);
238	    max-width: calc(100% - 2 * var(--gutter));
239	    padding: 12px 16px;
240	    border-radius: 12px;
241	    background: var(--text-primary);
242	    color: #FFFFFF;
243	    font-size: 14px;
244	    opacity: 0;
245	    pointer-events: none;
246	    transition: opacity 160ms ease, transform 160ms ease;
247	  }
248	  .toast.is-visible { opacity: 1; transform: translate(-50%, 0); }
249	
250	  @media (prefers-reduced-motion: reduce) {
251	    .toast { transition: none; }
252	    .spinner { animation-duration: 2.4s; }
253	  }
254	
255	  /* Preview-only state switcher; not part of the product UI */
256	  .preview {
257	    display: flex;
258	    flex-wrap: wrap;
259	    justify-content: center;
260	    gap: 6px;
261	    padding: 8px;
262	    font-size: 13px;
263	    background: #FFFFFF;
264	    border-bottom: 1px dashed var(--divider);
265	  }
266	  .preview button {
267	    padding: 6px 10px;
268	    border: 1px solid var(--divider);
269	    border-radius: 8px;
270	    background: none;
271	    cursor: pointer;
272	  }
273	  .preview button[aria-pressed="true"] { border-color: var(--text-primary); font-weight: 600; }
274	  @media print { .preview, .footer, .help, .toast { display: none !important; } }
275	</style>
276	</head>
277	<body>
278	  <nav class="preview" aria-label="Preview state (prototype only)"></nav>
279	
280	  <div class="app">
281	    <header class="header"><h1>Receipt</h1></header>
282	    <main class="body" id="receipt"></main>
283	    <footer class="footer" id="actions"></footer>
284	  </div>
285	
286	  <div class="toast" id="toast" role="status" aria-live="polite"></div>
287	
288	<script>
289	/*
290	 * Example data copied from the original screen. [REAL DATA] Replace with the
291	 * transaction from the payments API; the field names here are not an API contract.
292	 */
293	const TRANSACTION = {
294	  id: "TX-8F3K-29QD-7140",
295	  merchant: "Blue Bottle Coffee",
296	  merchantArea: "Hayes Valley",
297	  amount: 24.50,
298	  fee: 0,
299	  currency: "USD",
300	  method: "Wallet balance",
301	  balanceAfter: 175.50,
302	  balanceBefore: 200.00,
303	  createdAt: "2026-10-06T09:41:00",
304	};
305	
306	/*
307	 * Copy that depends on unconfirmed business rules. Each line is an ASSUMPTION
308	 * listed in the design notes; confirm before shipping.
309	 */
310	const COPY = {
311	  pendingMessage: "We'll update this screen when it's confirmed. It's safe to close it.",
312	  // ASSUMPTION: a failed wallet payment never charges or holds funds.
313	  failedMessage: "Your payment didn't go through. Your wallet wasn't charged.",
314	  // The dispute window was removed: "within 30 days" had no source (critique C-05).
315	  helpSub: "Get help or report an issue",
316	  helpSubFailed: "Contact support about this payment",
317	};
318	
319	const ICONS = {
320	  check: '<path d="M20 6 9 17l-5-5"/>',
321	  hourglass: '<path d="M5 22h14"/><path d="M5 2h14"/><path d="M17 22v-4.172a2 2 0 0 0-.586-1.414L12 12l-4.414 4.414A2 2 0 0 0 7 17.828V22"/><path d="M7 2v4.172a2 2 0 0 0 .586 1.414L12 12l4.414-4.414A2 2 0 0 0 17 6.172V2"/>',
322	  x: '<path d="M18 6 6 18"/><path d="m6 6 12 12"/>',
323	  copy: '<rect width="14" height="14" x="8" y="8" rx="2" ry="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/>',
324	  share: '<path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" x2="12" y1="2" y2="15"/>',
325	  lifeBuoy: '<circle cx="12" cy="12" r="10"/><path d="m4.93 4.93 4.24 4.24"/><path d="m14.83 9.17 4.24-4.24"/><path d="m14.83 14.83 4.24 4.24"/><path d="m9.17 14.83-4.24 4.24"/><circle cx="12" cy="12" r="4"/>',
326	  chevronRight: '<path d="m9 18 6-6-6-6"/>',
327	};
328	const icon = (name, size = 18, stroke = 2) =>
329	  `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]}</svg>`;
330	
331	/* Formatting follows the device locale instead of a hard-coded mix (critique C-10). */
332	const formatMoney = (value, currency) =>
333	  new Intl.NumberFormat(undefined, { style: "currency", currency }).format(value);
334	const formatDate = (iso) =>
335	  new Intl.DateTimeFormat(undefined, { weekday: "short", day: "numeric", month: "short", year: "numeric" }).format(new Date(iso));
336	const formatTime = (iso) =>
337	  new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(new Date(iso));
338	const escapeHtml = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
339	
340	const PILLS = {
341	  success: { icon: "check", label: "Payment successful" },
342	  pending: { icon: "hourglass", label: "Payment processing" },
343	  failed: { icon: "x", label: "Payment failed" },
344	};
345	
346	function row(label, value, { sub, strong } = {}) {
347	  return `<div class="row"><dt>${label}</dt><dd>
348	    <span class="row__value${strong ? " row__value--strong" : ""}">${escapeHtml(value)}</span>
349	    ${sub ? `<span class="row__sub">${escapeHtml(sub)}</span>` : ""}
350	  </dd></div>`;
351	}
352	
353	function renderReceipt(state, tx) {
354	  if (state === "loading") return renderLoading();
355	  const money = (v) => formatMoney(v, tx.currency);
356	  const pill = PILLS[state];
357	  const message = state === "pending" ? COPY.pendingMessage : state === "failed" ? COPY.failedMessage : "";
358	  const methodSub = {
359	    success: `Balance after payment: ${money(tx.balanceAfter)}`,
360	    pending: "",
361	    failed: `Balance: ${money(tx.balanceBefore)}`,
362	  }[state];
363	  const feeSub = tx.fee === 0 ? "No fee" : `Includes ${money(tx.fee)} fee`;
364	
365	  return `
366	    <section class="hero" aria-labelledby="amount">
367	      <span class="pill pill--${state}" role="status">
368	        <span class="pill__icon">${icon(pill.icon, 14, 2.5)}</span>${pill.label}
369	      </span>
370	      <p class="amount" id="amount">${money(tx.amount + tx.fee)}</p>
371	      <p class="merchant">to ${escapeHtml(tx.merchant)} · ${escapeHtml(tx.merchantArea)}</p>
372	      ${message ? `<p class="state-message">${message}</p>` : ""}
373	    </section>
374	
375	    <dl class="card">
376	      ${row("Paid with", tx.method, { sub: methodSub })}
377	      ${state === "success"
378	        ? row("Total paid", money(tx.amount + tx.fee), { sub: feeSub, strong: true })
379	        : row("Amount", money(tx.amount + tx.fee), { sub: state === "pending" ? feeSub : "" })}
380	      ${row("Date", formatDate(tx.createdAt), { sub: formatTime(tx.createdAt) })}
381	      <div class="row row--copy">
382	        <dt class="visually-hidden">Transaction ID</dt>
383	        <dd><button type="button" class="copy-button" data-action="copy" aria-label="Copy transaction ID ${tx.id.split("").join(" ")}">
384	          <span class="copy-button__label">Transaction ID</span>
385	          <span class="copy-button__value">${escapeHtml(tx.id)}${icon("copy")}</span>
386	        </button></dd>
387	      </div>
388	    </dl>
389	
390	    <button type="button" class="help" data-action="help">
391	      ${icon("lifeBuoy", 22)}
392	      <span class="help__text">
393	        <span class="help__title">Problem with this payment?</span>
394	        <span class="help__sub">${state === "failed" ? COPY.helpSubFailed : COPY.helpSub}</span>
395	      </span>
396	      ${icon("chevronRight", 20)}
397	    </button>`;
398	}
399	
400	function renderLoading() {
401	  const bone = (w, h) => `<span class="bone" style="width:${w}px;height:${h}px"></span>`;
402	  const rows = [120, 80, 110, 150]
403	    .map((w) => `<div class="row" style="align-items:center">${bone(90, 14)}${bone(w, 14)}</div>`)
404	    .join("");
405	  return `
406	    <p class="visually-hidden" role="status">Loading receipt</p>
407	    <div class="hero" aria-hidden="true">${bone(170, 30)}${bone(180, 52)}${bone(220, 18)}</div>
408	    <div class="card" aria-hidden="true">${rows}</div>
409	    <button type="button" class="help" data-action="help">
410	      ${icon("lifeBuoy", 22)}
411	      <span class="help__text">
412	        <span class="help__title">Problem with this payment?</span>
413	        <span class="help__sub">${COPY.helpSub}</span>
414	      </span>
415	      ${icon("chevronRight", 20)}
416	    </button>`;
417	}
418	
419	function renderActions(state) {
420	  const done = (variant) => `<button type="button" class="button button--${variant}" data-action="done">Done</button>`;
421	  if (state === "success") {
422	    return `<button type="button" class="button button--secondary" data-action="share">${icon("share")}<span>Share receipt</span></button>${done("primary")}`;
423	  }
424	  if (state === "failed") {
425	    // ASSUMPTION: the product supports retrying a payment. If not, show only Done as primary.
426	    return `${done("secondary")}<button type="button" class="button button--primary" data-action="retry">Try again</button>`;
427	  }
428	  return done("primary");
429	}
430	
431	/* Toast */
432	const toastEl = document.getElementById("toast");
433	let toastTimer;
434	function toast(text) {
435	  clearTimeout(toastTimer);
436	  toastEl.textContent = text;
437	  toastEl.classList.add("is-visible");
438	  toastTimer = setTimeout(() => toastEl.classList.remove("is-visible"), 2000);
439	}
440	
441	/* Actions */
442	async function copyId(tx) {
443	  try {
444	    await navigator.clipboard.writeText(tx.id);
445	    navigator.vibrate?.(10);
446	    toast("Transaction ID copied");
447	  } catch {
448	    toast("Couldn't copy. Press and hold the ID to copy it.");
449	  }
450	}
451	
452	async function shareReceipt(button, tx) {
453	  if (button.getAttribute("aria-busy") === "true") return;
454	  const label = button.innerHTML;
455	  button.setAttribute("aria-busy", "true");
456	  button.innerHTML = '<span class="spinner" aria-hidden="true"></span><span>Preparing…</span>';
457	  try {
458	    const text = `Paid ${formatMoney(tx.amount + tx.fee, tx.currency)} to ${tx.merchant} on ${formatDate(tx.createdAt)}, ${formatTime(tx.createdAt)}. Transaction ID ${tx.id}.`;
459	    if (navigator.share) {
460	      // A receipt PDF from the backend would be attached here; none exists in this prototype.
461	      await navigator.share({ title: "Payment receipt", text });
462	    } else {
463	      // No share sheet (most desktop browsers): the print dialog offers "Save as PDF".
464	      window.print();
465	    }
466	  } catch (err) {
467	    if (err?.name !== "AbortError") toast("Couldn't share the receipt. Try again.");
468	  } finally {
469	    button.removeAttribute("aria-busy");
470	    button.innerHTML = label;
471	  }
472	}
473	
474	/*
475	 * Navigation belongs to the host app. These events are the integration points;
476	 * the prototype only logs them.
477	 */
478	function emit(name) {
479	  document.dispatchEvent(new CustomEvent(`receipt:${name}`, { detail: { id: TRANSACTION.id } }));
480	}
481	
482	/* State */
483	const STATES = ["success", "pending", "failed", "loading"];
484	let current;
485	
486	function setState(state) {
487	  if (!STATES.includes(state)) state = "success";
488	  current = state;
489	  const main = document.getElementById("receipt");
490	  main.setAttribute("aria-busy", String(state === "loading"));
491	  main.innerHTML = renderReceipt(state, TRANSACTION);
492	  document.getElementById("actions").innerHTML = renderActions(state);
493	  document.querySelectorAll(".preview button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.state === state)));
494	  const url = new URL(location.href);
495	  url.searchParams.set("state", state);
496	  history.replaceState(null, "", url);
497	}
498	
499	document.addEventListener("click", (e) => {
500	  const el = e.target.closest("[data-action]");
501	  if (!el) return;
502	  const action = el.dataset.action;
503	  if (action === "copy") copyId(TRANSACTION);
504	  else if (action === "share") shareReceipt(el, TRANSACTION);
505	  else emit(action);
506	});
507	["done", "help", "retry"].forEach((n) => document.addEventListener(`receipt:${n}`, (e) => console.info(`receipt:${n}`, e.detail)));
508	
509	/* Preview switcher (prototype only) */
510	document.querySelector(".preview").innerHTML = STATES
511	  .map((s) => `<button type="button" data-state="${s}" aria-pressed="false">${s[0].toUpperCase() + s.slice(1)}</button>`)
512	  .join("");
513	document.querySelector(".preview").addEventListener("click", (e) => {
514	  const b = e.target.closest("button[data-state]");
515	  if (b) setState(b.dataset.state);
516	});
517	
518	/* The host app can move a pending receipt to success or failed without a reload. */
519	window.receipt = { setState };
520	
521	setState(new URLSearchParams(location.search).get("state") || "success");
522	</script>
523	</body>
524	</html>
